// apply.mjs — membuat semua file M2 + M3 Portal DTP di path yang benar.
// Cara pakai: taruh file ini di root project (sejajar package.json), lalu jalankan:
//     node apply.mjs
// Aman dijalankan berkali-kali (akan menimpa file dengan versi terbaru).

import { writeFileSync, mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

const FILES = [
  ['src/routes/+layout.svelte', ''],
  ['src/routes/+page.svelte', ''],
  ['src/lib/utils.ts', ''],
  ['src/lib/components/ui/button/button.svelte', ''],
  ['src/lib/components/ui/button/index.ts', ''],
  ['src/lib/components/ui/card/card.svelte', ''],
  ['src/lib/components/ui/card/card-header.svelte', ''],
  ['src/lib/components/ui/card/card-title.svelte', ''],
  ['src/lib/components/ui/card/card-content.svelte', ''],
  ['src/lib/components/ui/card/index.ts', ''],
  ['src/lib/components/ui/sheet/sheet-overlay.svelte', ''],
  ['src/lib/components/ui/sheet/sheet-content.svelte', ''],
  ['src/lib/components/ui/sheet/sheet-header.svelte', ''],
  ['src/lib/components/ui/sheet/sheet-footer.svelte', ''],
  ['src/lib/components/ui/sheet/sheet-title.svelte', ''],
  ['src/lib/components/ui/sheet/sheet-description.svelte', ''],
  ['src/lib/components/ui/sheet/sheet-trigger.svelte', ''],
  ['src/lib/components/ui/sheet/sheet-close.svelte', ''],
  ['src/lib/components/ui/sheet/index.ts', ''],
  ['src/lib/hooks/is-mobile.svelte.ts', ''],
  ['src/lib/types/nav.ts', ''],
  ['src/lib/types/content.ts', ''],
  ['src/lib/data/nav.ts', ''],
  ['src/lib/data/articles.json', ''],
  ['src/lib/data/events.json', ''],
  ['src/lib/data/downloads.json', ''],
  ['src/lib/data/news.json', ''],
  ['src/lib/data/announcements.json', ''],
  ['src/lib/components/layout/topbar.svelte', ''],
  ['src/lib/components/layout/site-header.svelte', ''],
  ['src/lib/components/layout/main-nav.svelte', ''],
  ['src/lib/components/layout/mobile-nav.svelte', ''],
  ['src/lib/components/layout/site-footer.svelte', ''],
  ['src/lib/components/layout/index.ts', ''],
  ['src/lib/components/shared/section-heading.svelte', ''],
  ['src/lib/components/shared/calendar-panel.svelte', ''],
  ['src/lib/components/shared/announcement-panel.svelte', ''],
  ['src/lib/components/home/hero.svelte', ''],
  ['src/lib/components/home/about-section.svelte', ''],
  ['src/lib/components/home/feature-grid.svelte', ''],
  ['src/lib/components/home/info-panel.svelte', ''],
  ['src/lib/components/home/news-section.svelte', ''],
  ['src/lib/components/home/contact-section.svelte', ''],
  ['src/lib/components/home/quick-mail-login.svelte', ''],
  ['src/lib/components/home/index.ts', '']
];

let ok = 0;
for (const [path, b64] of FILES) {
  try {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, Buffer.from(b64, 'base64'));
    console.log('  dibuat:', path);
    ok++;
  } catch (e) {
    console.error('  GAGAL :', path, '-', e.message);
  }
}
console.log('\nSelesai. ' + ok + '/' + FILES.length + ' file dibuat.');
console.log('Selanjutnya: hentikan dev server (Ctrl+C) lalu jalankan lagi: npm run dev');
